package org.jsoup.nodes;

import org.junit.Test;
import static org.junit.Assert.*;
import org.jsoup.nodes.Document;
import org.jsoup.parser.ParseSettings;
import org.jsoup.parser.Parser;
import javax.annotation.Nullable;
import java.io.ByteArrayOutputStream;
import java.io.IOException;

public class CommentTest {

    @Test
    public void newCommentWithData() {
        String data = "This is a comment";
        Comment comment = new Comment(data);
        assertNotNull(comment);
        assertEquals(data, comment.getData());
    }

    @Test
    public void nodeNameIsComment() {
        Comment comment = new Comment("data");
        assertEquals("comment", comment.nodeName());
    }

    @Test
    public void getDataReturnsCorrectData() {
        String data = "This is a comment";
        Comment comment = new Comment(data);
        assertEquals(data, comment.getData());
    }

    @Test
    public void setDataUpdatesData() {
        String originalData = "This is a comment";
        Comment comment = new Comment(originalData);
        String newData = "New data";
        comment.setData(newData);
        assertEquals(newData, comment.getData());
    }

    @Test
    public void outerHtmlHeadAddsDataAsCommentTag() throws IOException {
        Comment comment = new Comment("data");
        ByteArrayOutputStream out = new ByteArrayOutputStream();
        Document.OutputSettings outSettings = new Document.OutputSettings();
        Appendable accum = out;
        int depth = 0;
        comment.outerHtmlHead(accum, depth, outSettings);
        String output = out.toString();
        assertTrue(output.contains("<!--"));
        assertTrue(output.contains("-->"));
    }

    @Test
    public void outerHtmlTailAddsDataAsCommentTag() throws IOException {
        Comment comment = new Comment("data");
        ByteArrayOutputStream out = new ByteArrayOutputStream();
        Document.OutputSettings outSettings = new Document.OutputSettings();
        Appendable accum = out;
        int depth = 0;
        comment.outerHtmlTail(accum, depth, outSettings);
        String output = out.toString();
        assertTrue(output.contains("<!--"));
        assertTrue(output.contains("-->"));
    }

    @Test
    public void toStringReturnsCorrectString() {
        Comment comment = new Comment("data");
        assertEquals("<!-- data -->", comment.toString());
    }

    @Test
    public void cloneCreatesNewComment() {
        Comment comment = new Comment("data");
        Comment cloned = comment.clone();
        assertNotNull(cloned);
        assertNotSame(comment, cloned);
    }

    @Test
    public void isXmlDeclarationReturnsFalse() {
        Comment comment = new Comment("data");
        assertFalse(comment.isXmlDeclaration());
    }

    @Test
    public void asXmlDeclarationReturnsNullWhenNotDeclaration() {
        Comment comment = new Comment("data");
        assertNull(comment.asXmlDeclaration());
    }

    @Test
    public void asXmlDeclarationReturnsCorrectDeclaration() throws IOException {
        XmlDeclaration declaration = new XmlDeclaration();
        ByteArrayOutputStream out = new ByteArrayOutputStream();
        Document.OutputSettings outSettings = new Document.OutputSettings();
        Appendable accum = out;
        int depth = 0;
        Parser parser = new Parser(ParseSettings.STRICT);
        Document document = parser.parse(declaration.toString(), null, outSettings, 0, 1);
        Comment comment = (Comment) document.head().children().first();
        assertNotNull(comment.asXmlDeclaration());
        assertEquals(declaration, comment.asXmlDeclaration());
    }
}
